// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadCaveat = makeLoadFont('Caveat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: caveatFamily } = loadCaveat();



export type CalendarMarksProps = Record<string, any>;

const CalendarMarks: React.FC<CalendarMarksProps> = ({
  backgroundColor = "#f9f9f6",
  transparentBackground = false,
  durationInSeconds = 8,
  calendarColor = "#1a1a1a",
  accentColor1 = "#2563eb",
  accentColor2 = "#d97706",
  accentColor3 = "#dc2626",
  calendarMonth = "MAY",
  marker1Date = 2,
  marker1Text = "start here",
  marker2Date = 7,
  marker2Text = "Deliver",
  marker3Date = 14,
  marker3Text = "actually delivered",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calendar Layout Calculations
  const cols = 7;
  const daysInMonth = 31;
  const startOffset = 3; // May 2024 starts on Wednesday
  const gridWidth = width * 0.9;
  const cellWidth = gridWidth / cols;
  const cellHeight = 150;
  const gridStartX = (width - gridWidth) / 2;
  
  const headerHeight = 200;
  const dowHeight = 100;
  const totalGridHeight = Math.ceil((daysInMonth + startOffset) / cols) * cellHeight;
  const totalContentHeight = headerHeight + dowHeight + totalGridHeight;
  const startY = (height - totalContentHeight) / 2;
  const gridStartY = startY + headerHeight + dowHeight;

  const daysOfWeek = ["S", "M", "T", "W", "T", "F", "S"];

  // Helper to get exact x, y center for a date
  const getDateCenter = (date: number) => {
    const index = date + startOffset - 1;
    const c = index % cols;
    const r = Math.floor(index / cols);
    return {
      x: gridStartX + c * cellWidth + cellWidth / 2,
      y: gridStartY + r * cellHeight + cellHeight / 2,
      col: c,
      row: r,
    };
  };

  // Define marker data with fixed animation timings and layout hints
  const markers = [
    {
      date: marker1Date,
      text: marker1Text,
      color: accentColor1,
      startFrame: 30,
      angle: -150 * (Math.PI / 180),
      distance: 220,
      rotation: -4,
    },
    {
      date: marker2Date,
      text: marker2Text,
      color: accentColor2,
      startFrame: 90,
      angle: 15 * (Math.PI / 180),
      distance: 240,
      rotation: 3,
    },
    {
      date: marker3Date,
      text: marker3Text,
      color: accentColor3,
      startFrame: 150,
      angle: 35 * (Math.PI / 180),
      distance: 280,
      rotation: -2,
    },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* 1. Base Calendar Grid */}
      <div
        style={{
          position: "absolute",
          top: startY,
          left: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
        }}
      >
        <div
          style={{
            height: headerHeight,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 90,
            fontWeight: 800,
            color: calendarColor,
            letterSpacing: "0.2em",
            opacity: interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" }),
            transform: `translateY(${interpolate(frame, [0, 15], [20, 0], { extrapolateRight: "clamp" })}px)`,
          }}
        >
          {calendarMonth}
        </div>

        <div
          style={{
            width: gridWidth,
            height: dowHeight,
            display: "flex",
            borderBottom: `2px solid ${calendarColor}20`,
          }}
        >
          {daysOfWeek.map((day, i) => (
            <div
              key={`dow-${i}`}
              style={{
                width: cellWidth,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: 36,
                fontWeight: 600,
                color: `${calendarColor}80`,
              }}
            >
              {day}
            </div>
          ))}
        </div>

        <div
          style={{
            width: gridWidth,
            height: totalGridHeight,
            position: "relative",
          }}
        >
          {Array.from({ length: daysInMonth }).map((_, i) => {
            const date = i + 1;
            const index = date + startOffset - 1;
            const c = index % cols;
            const r = Math.floor(index / cols);
            const x = c * cellWidth;
            const y = r * cellHeight;

            const popIn = spring({
              frame: frame - (5 + date * 0.5),
              fps,
              config: { damping: 14 },
            });

            return (
              <div
                key={`date-${date}`}
                style={{
                  position: "absolute",
                  left: x,
                  top: y,
                  width: cellWidth,
                  height: cellHeight,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 50,
                  fontWeight: 500,
                  color: calendarColor,
                  transform: `scale(${popIn})`,
                  opacity: popIn,
                }}
              >
                {date}
              </div>
            );
          })}
        </div>
      </div>

      {/* 2. SVG Overlay for Drawings */}
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          pointerEvents: "none",
        }}
      >
        {markers.map((m, i) => {
          const { x: dateCenterX, y: dateCenterY } = getDateCenter(m.date);
          const textCenterX = dateCenterX + Math.cos(m.angle) * m.distance;
          const textCenterY = dateCenterY + Math.sin(m.angle) * m.distance;

          const textWidth = Math.max(200, m.text.length * 32 + 60);
          const textHeight = 110;

          const ellipseRx = textWidth / 2;
          const ellipseRy = textHeight / 2;
          const ellipsePerimeter = 2 * Math.PI * Math.sqrt((ellipseRx ** 2 + ellipseRy ** 2) / 2);

          const circleR = cellWidth * 0.38;
          const circlePerimeter = 2 * Math.PI * circleR;

          // Connect edge of circle to edge of ellipse
          const lineStartX = dateCenterX + Math.cos(m.angle) * circleR;
          const lineStartY = dateCenterY + Math.sin(m.angle) * circleR;
          const lineEndX = textCenterX - Math.cos(m.angle) * ellipseRx;
          const lineEndY = textCenterY - Math.sin(m.angle) * ellipseRy;
          const lineLength = Math.sqrt((lineEndX - lineStartX) ** 2 + (lineEndY - lineStartY) ** 2);

          // Staggered Drawing Progress
          const circleDraw = interpolate(frame, [m.startFrame, m.startFrame + 15], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const lineDraw = interpolate(frame, [m.startFrame + 10, m.startFrame + 25], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const ellipseDraw = interpolate(frame, [m.startFrame + 20, m.startFrame + 40], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          return (
            <g key={`svg-marker-${i}`}>
              {/* Date Circle */}
              <circle
                cx={dateCenterX}
                cy={dateCenterY}
                r={circleR}
                fill="none"
                stroke={m.color}
                strokeWidth={8}
                strokeLinecap="round"
                strokeDasharray={circlePerimeter}
                strokeDashoffset={circlePerimeter * (1 - circleDraw)}
                style={{
                  transformOrigin: `${dateCenterX}px ${dateCenterY}px`,
                  transform: `rotate(-90deg)`,
                }}
              />
              {/* Connecting Line */}
              <line
                x1={lineStartX}
                y1={lineStartY}
                x2={lineStartX + (lineEndX - lineStartX) * lineDraw}
                y2={lineStartY + (lineEndY - lineStartY) * lineDraw}
                stroke={m.color}
                strokeWidth={6}
                strokeLinecap="round"
              />
              {/* Text Ellipse */}
              <ellipse
                cx={textCenterX}
                cy={textCenterY}
                rx={ellipseRx}
                ry={ellipseRy}
                fill="none"
                stroke={m.color}
                strokeWidth={8}
                strokeLinecap="round"
                strokeDasharray={ellipsePerimeter}
                strokeDashoffset={ellipsePerimeter * (1 - ellipseDraw)}
                style={{
                  transformOrigin: `${textCenterX}px ${textCenterY}px`,
                  transform: `rotate(${m.rotation}deg)`,
                }}
              />
            </g>
          );
        })}
      </svg>

      {/* 3. Text Overlay */}
      {markers.map((m, i) => {
        const { x: dateCenterX, y: dateCenterY } = getDateCenter(m.date);
        const textCenterX = dateCenterX + Math.cos(m.angle) * m.distance;
        const textCenterY = dateCenterY + Math.sin(m.angle) * m.distance;
        const textWidth = Math.max(200, m.text.length * 32 + 60);
        const textHeight = 110;

        const textScale = spring({
          frame: frame - (m.startFrame + 25),
          fps,
          config: { damping: 12 },
        });

        const textOpacity = interpolate(frame, [m.startFrame + 20, m.startFrame + 30], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={`text-marker-${i}`}
            style={{
              position: "absolute",
              left: textCenterX - textWidth / 2,
              top: textCenterY - textHeight / 2,
              width: textWidth,
              height: textHeight,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: caveatFamily,
              fontSize: 65,
              fontWeight: 700,
              color: m.color,
              opacity: textOpacity,
              transform: `scale(${textScale}) rotate(${m.rotation}deg)`,
              textAlign: "center",
            }}
          >
            {m.text}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default CalendarMarks;